/// SplitMix64, bit-identical to `cjc_repro::Rng::next_u64` and to the
/// Python mirror in `tests/refs/binned_exact.py`.
struct Sm(u64);
impl Sm {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9e3779b97f4a7c15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d049bb133111eb);
        z ^ (z >> 31)
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

/// Mirror of `splitmix_vec` in `tests/refs/binned_exact.py`.
fn splitmix_vec(seed: u64, n: usize, wide: bool) -> Vec<f64> {
    let mut r = Sm(seed);
    (0..n)
        .map(|_| {
            let u = r.next();
            let v = r.next();
            let sign = u >> 63;
            let e = if wide {
                let e = (u >> 52) & 0x7FF;
                if e == 0x7FF {
                    0x7FE
                } else {
                    e
                }
            } else {
                983 + ((u >> 52) & 0x7FF) % 81
            };
            f64::from_bits((sign << 63) | (e << 52) | (v >> 12))
        })
        .collect()
}

fn shuffle(xs: &mut [f64], r: &mut Sm) {
    for i in (1..xs.len()).rev() {
        let j = r.below(i + 1);
        xs.swap(i, j);
    }
}

/// Split `xs` into random contiguous chunks, accumulate each chunk
/// separately, then merge the partial accumulators in a random tree order.
fn chunked_merged(xs: &[f64], r: &mut Sm) -> f64 {
    let mut parts: Vec<BinnedAccumulatorF64> = Vec::new();
    let mut i = 0;
    while i < xs.len() {
        let len = 1 + r.below(xs.len() - i);
        let mut a = BinnedAccumulatorF64::new();
        a.add_slice(&xs[i..i + len]);
        parts.push(a);
        i += len;
    }
    if parts.is_empty() {
        parts.push(BinnedAccumulatorF64::new());
    }
    while parts.len() > 1 {
        let a = r.below(parts.len());
        let other = parts.swap_remove(a);
        let b = r.below(parts.len());
        parts[b].merge(&other);
    }
    parts[0].finalize()
}

fn bits_of(xs: &[u64]) -> Vec<f64> {
    xs.iter().map(|&b| f64::from_bits(b)).collect()
}

fn fmt(b: u64) -> String {
    format!("{:?} (0x{b:016x})", f64::from_bits(b))
}

// ---------------------------------------------------------------------------
// Oracle tests
// ---------------------------------------------------------------------------

#[test]
fn oracle_exact_rounded_sum() {
    let mut failures = Vec::new();
    for &(name, inputs, expected) in ORACLE_CASES {
        let xs = bits_of(inputs);
        let got = binned_sum_f64(&xs).to_bits();
        if got != expected {
            failures.push(format!("{name}: got {} expected {}", fmt(got), fmt(expected)));
        }
    }
    assert!(failures.is_empty(), "oracle mismatches:\n{}", failures.join("\n"));
}

#[test]
fn oracle_cases_all_orders_and_chunkings() {
    let mut r = Sm(0xC0FFEE);
    let mut failures = Vec::new();
    for &(name, inputs, expected) in ORACLE_CASES {
        let base = bits_of(inputs);
        for trial in 0..64 {
            let mut xs = base.clone();
            shuffle(&mut xs, &mut r);
            let seq = binned_sum_f64(&xs).to_bits();
            let chk = chunked_merged(&xs, &mut r).to_bits();
            if seq != expected || chk != expected {
                failures.push(format!(
                    "{name} trial {trial}: seq {} chunked {} expected {}",
                    fmt(seq),
                    fmt(chk),
                    fmt(expected)
                ));
                break;
            }
        }
    }
    assert!(failures.is_empty(), "order dependence:\n{}", failures.join("\n"));
}

#[test]
fn probe_p5_exact() {
    let b = 1.0000000000000002_f64;
    let exact = 3.0000000000000004_f64.to_bits();
    assert_eq!(binned_sum_f64(&[1.0, b, b]).to_bits(), exact);
    assert_eq!(binned_sum_f64(&[b, b, 1.0]).to_bits(), exact);
    assert_eq!(binned_sum_f64(&[b, 1.0, b]).to_bits(), exact);
}

// ---------------------------------------------------------------------------
// Special-value semantics (documented in cjc-runtime/src/accumulator.rs)
// ---------------------------------------------------------------------------

#[test]
fn special_values_policy() {
    assert!(binned_sum_f64(&[1.0, f64::NAN, 2.0]).is_nan());
    assert!(binned_sum_f64(&[f64::INFINITY, f64::NEG_INFINITY]).is_nan());
    assert!(binned_sum_f64(&[f64::INFINITY, f64::NAN]).is_nan());
    assert_eq!(binned_sum_f64(&[1.0, f64::INFINITY, -1e308]), f64::INFINITY);
    assert_eq!(binned_sum_f64(&[f64::NEG_INFINITY, 1e308, 1e308]), f64::NEG_INFINITY);
    // Zero results are always +0.0 (pre-existing behaviour, order-free).
    assert_eq!(binned_sum_f64(&[]).to_bits(), 0.0f64.to_bits());
    assert_eq!(binned_sum_f64(&[-0.0]).to_bits(), 0.0f64.to_bits());
    assert_eq!(binned_sum_f64(&[-0.0, -0.0]).to_bits(), 0.0f64.to_bits());
    assert_eq!(binned_sum_f64(&[1.5, -1.5]).to_bits(), 0.0f64.to_bits());
    // A finite exact sum beyond the f64 range rounds to +-Inf; an
    // intermediate overflow that later cancels does not.
    assert_eq!(binned_sum_f64(&[f64::MAX, f64::MAX]), f64::INFINITY);
    assert_eq!(binned_sum_f64(&[f64::MAX, f64::MAX, -f64::MAX]), f64::MAX);
    assert_eq!(binned_sum_f64(&[f64::MAX, -f64::MAX, f64::MAX]), f64::MAX);
    // NaN-ness is merge-order independent too.
    let mut a = BinnedAccumulatorF64::new();
    a.add(1.0);
    let mut b = BinnedAccumulatorF64::new();
    b.add(f64::NAN);
    let mut ab = a.clone();
    ab.merge(&b);
    let mut ba = b.clone();
    ba.merge(&a);
    assert!(ab.finalize().is_nan() && ba.finalize().is_nan());
    assert_eq!(ab.count(), 2);
}

// ---------------------------------------------------------------------------
// Property tests (seeded, deterministic)
// ---------------------------------------------------------------------------

/// Fraction-oracle sample: 6 seeded vectors (257..5000 elements), each
/// checked in order, under 8 permutations and 8 random chunk/merge trees.
#[test]
fn property_splitmix_exact_oracle_sample() {
    let mut r = Sm(7);
    for &(seed, n, wide, expected) in SPLITMIX_ORACLE {
        let mut xs = splitmix_vec(seed, n, wide);
        assert_eq!(binned_sum_f64(&xs).to_bits(), expected, "seed {seed} in order");
        for _ in 0..8 {
            shuffle(&mut xs, &mut r);
            assert_eq!(binned_sum_f64(&xs).to_bits(), expected, "seed {seed} permuted");
            assert_eq!(chunked_merged(&xs, &mut r).to_bits(), expected, "seed {seed} chunked");
        }
    }
}

/// 200 random vectors (n in 1..=2000, narrow and full-exponent-range),
/// 16 permutations + 16 random chunk/merge trees each: exactly one distinct
/// bit pattern per vector.
#[test]
fn property_permutation_and_chunking_invariance() {
    let mut r = Sm(0x5EED);
    for case in 0..200u64 {
        let n = 1 + r.below(2000);
        let wide = case % 3 == 0;
        let mut xs = splitmix_vec(1000 + case, n, wide);
        let reference = binned_sum_f64(&xs).to_bits();
        let mut distinct = std::collections::BTreeSet::new();
        distinct.insert(reference);
        for _ in 0..16 {
            shuffle(&mut xs, &mut r);
            distinct.insert(binned_sum_f64(&xs).to_bits());
            distinct.insert(chunked_merged(&xs, &mut r).to_bits());
        }
        assert_eq!(distinct.len(), 1, "case {case} (n={n}, wide={wide}): {distinct:x?}");
    }
}

/// Any finite f64 (normal, subnormal, zero) across the full exponent range.
fn wide_f64() -> impl Strategy<Value = f64> {
    proptest::num::f64::NORMAL | proptest::num::f64::SUBNORMAL | proptest::num::f64::ZERO
}

/// Mixed-sign values with exponents in [2^-10, 2^11): dense same-bin
/// collisions with partial sums that leave the bin -- the P5 failure mode.
fn narrow_f64() -> impl Strategy<Value = f64> {
    (0u64..(1 << 52), 1013u64..1034, any::<bool>())
        .prop_map(|(m, e, s)| f64::from_bits(((s as u64) << 63) | (e << 52) | m))
}

fn check_invariance(xs: &[f64], seed: u64) -> Result<(), TestCaseError> {
    let reference = binned_sum_f64(xs).to_bits();
    let mut ys = xs.to_vec();
    let mut r = Sm(seed);
    shuffle(&mut ys, &mut r);
    prop_assert_eq!(binned_sum_f64(&ys).to_bits(), reference);
    prop_assert_eq!(chunked_merged(&ys, &mut r).to_bits(), reference);
    Ok(())
}

proptest! {
    #![proptest_config(ProptestConfig { cases: 256, ..ProptestConfig::default() })]
    #[test]
    fn proptest_narrow_order_and_merge_invariance(
        xs in proptest::collection::vec(narrow_f64(), 0..300),
        seed in any::<u64>(),
    ) {
        check_invariance(&xs, seed)?;
    }

    #[test]
    fn proptest_mixed_order_and_merge_invariance(
        xs in proptest::collection::vec(prop_oneof![1 => wide_f64(), 9 => narrow_f64()], 0..300),
        seed in any::<u64>(),
    ) {
        check_invariance(&xs, seed)?;
    }
}

// ---------------------------------------------------------------------------
// Both executors, through .cjcl
// ---------------------------------------------------------------------------

fn run_eval(src: &str, seed: u64) -> Vec<String> {
    let (program, _diag) = cjc_parser::parse_source(src);
    let mut interp = cjc_eval::Interpreter::new(seed);
    let _ = interp.exec(&program);
    interp.output
}

fn run_mir(src: &str, seed: u64) -> Vec<String> {
    let (program, _diag) = cjc_parser::parse_source(src);
    let (_, executor) = cjc_mir_exec::run_program_with_executor(&program, seed)
        .unwrap_or_else(|e| panic!("MIR-exec failed: {e}"));
    executor.output
}

fn assert_parity(src: &str) -> Vec<String> {
    let eval_out = run_eval(src, 42);
    let mir_out = run_mir(src, 42);
    assert_eq!(
        eval_out, mir_out,
        "Parity mismatch!\nEval: {eval_out:?}\nMIR:  {mir_out:?}"
    );
    eval_out
}

#[test]
fn cjcl_probe_p5_parity_and_exact() {
    let out = assert_parity(
        r#"
fn main() {
    let a = 1.0;
    let b = 1.0000000000000002;
    let t1 = Tensor.from_vec([a, b, b], [3]);
    let t2 = Tensor.from_vec([b, b, a], [3]);
    let t3 = Tensor.from_vec([b, a, b], [3]);
    print(t1.sum());
    print(t2.sum());
    print(t3.sum());
    print(t1.sum() == t2.sum());
}
"#,
    );
    assert_eq!(
        out,
        vec!["3.0000000000000004", "3.0000000000000004", "3.0000000000000004", "true"]
    );
}

#[test]
fn cjcl_cancellation_parity_and_exact() {
    let out = assert_parity(
        r#"
fn main() {
    let t1 = Tensor.from_vec([1e308, 1e308, -1e308], [3]);
    let t2 = Tensor.from_vec([1e308, -1e308, 1e308], [3]);
    print(t1.sum() == t2.sum());
    print(t1.sum());
}
"#,
    );
    assert_eq!(out[0], "true");
    assert_eq!(out[1].parse::<f64>().unwrap(), 1e308);
}
